export interface LayersIndexAnswer {
  schemaVersion: number;
  capabilities: {
    [key: string]: unknown;
  };
  categories: unknown[];
  layers: {
    id: string;
    sourceMapId: string;
    name: string;
    category: string;
    renderer: string;
    geometryType: string;
    [key: string]: unknown;
  }[];
  [key: string]: unknown;
}

/** GET /api/v1/layers (path=<absent>): The full render metadata */
export interface LayersDocumentAnswer {
  schemaVersion: number;
  categories: unknown[];
  layers: {
    id: string;
    sourceMapId: string;
    name: string;
    category: string;
    renderer: string;
    geometryType: string;
    [key: string]: unknown;
  }[];
  [key: string]: unknown;
}

/** GET /api/v1/layers (path=<id>/duplicates): One layer's duplicate-feature-id sidecar */
export interface LayersDuplicatesAnswer {
  layerId: string;
  sourceMapId: string;
  featureCount: number;
  duplicateFeatureIds: unknown[];
  [key: string]: unknown;
}

/** GET /api/v1/layers (path=<id>): One layer's full record */
export interface LayersLayerAnswer {
  id: string;
  sourceMapId: string;
  name: string;
  category: string;
  renderer: string;
  geometryType: string;
  minzoom: number;
  maxzoom: number;
  [key: string]: unknown;
}

/** /api/v1/layers: its JSON error answers (4xx and 5xx). */
export interface LayersErrorAnswer {
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/search (): Map features whose name contains q, best first */
export interface SearchResultsAnswer {
  results: {
    score: number;
    [key: string]: unknown;
  }[];
  [key: string]: unknown;
}

/** /api/v1/search: its JSON error answers (4xx and 5xx). */
export interface SearchErrorAnswer {
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/spatial (mapId=<given>): One map's features in the bounding box */
export interface SpatialFeaturesAnswer {
  features: unknown[];
  [key: string]: unknown;
}

/** GET /api/v1/spatial (mapIds=<given>): Several maps' features at once (mapIds=a,b,c, up to 40), keyed by map id, each as the features variant answers */
export interface SpatialBatchAnswer {
  maps: {
    [key: string]: unknown[];
  };
  [key: string]: unknown;
}

/** /api/v1/spatial: its JSON error answers (4xx and 5xx). */
export interface SpatialErrorAnswer {
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/data-index (): One level of the published files under a prefix (the approved prefixes at the root) */
export interface DataIndexListingAnswer {
  ok: true;
  scope: string;
  prefix: string;
  folders: {
    prefix: string;
    name: string;
    [key: string]: unknown;
  }[];
  files: {
    key: string;
    name: string;
    size: number;
    url: string;
    [key: string]: unknown;
  }[];
  truncated: boolean;
  cursor: string | null;
  [key: string]: unknown;
}

/** /api/v1/data-index: its JSON error answers (4xx and 5xx). */
export interface DataIndexErrorAnswer {
  ok: false;
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/proni/node (ref=<given>): One catalogue node with its ancestors and children */
export interface ProniNodeNodeAnswer {
  item: {
    ref: string;
    slug: string;
    title: string;
    level: string;
    dates: string;
    description: string;
    access: string;
    hasChildren: boolean;
    fond: string;
    extractedDates: {
      [key: string]: unknown;
    } | null;
    [key: string]: unknown;
  };
  ancestors: {
    ref: string;
    slug: string;
    title: string;
    [key: string]: unknown;
  }[];
  children: {
    ref: string;
    slug: string;
    title: string;
    level: string;
    dates: string;
    hasChildren: boolean;
    [key: string]: unknown;
  }[];
  [key: string]: unknown;
}

/** GET /api/v1/proni/node (): The top-level fonds */
export interface ProniNodeRootsAnswer {
  roots: {
    ref: string;
    slug: string;
    title: string;
    level: string;
    dates: string;
    hasChildren: boolean;
    [key: string]: unknown;
  }[];
  count: number;
  [key: string]: unknown;
}

/** /api/v1/proni/node: its JSON error answers (4xx and 5xx). */
export interface ProniNodeErrorAnswer {
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/proni/search (): A page of matches (one more than limit, to show there is a next page) */
export interface ProniSearchResultsAnswer {
  query: string;
  results: {
    ref: string;
    slug: string;
    title: string;
    level: string;
    dates: string;
    parent: string;
    hasChildren: boolean;
    fond: string;
    description: string;
    descTruncated: boolean;
    exact: boolean;
    url: string;
    [key: string]: unknown;
  }[];
  count: number;
  [key: string]: unknown;
}

/** /api/v1/proni/search: its JSON error answers (4xx and 5xx). */
export interface ProniSearchErrorAnswer {
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/proni/count (): How many records match (exact when known) */
export interface ProniCountCountAnswer {
  count: number | null;
  exact: boolean;
  [key: string]: unknown;
}

/** /api/v1/proni/count: its JSON error answers (4xx and 5xx). */
export interface ProniCountErrorAnswer {
  error: string;
  [key: string]: unknown;
}

/** GET /api/v1/proni/export (): Every match as CSV, streamed */
export type ProniExportCsvAnswer = unknown;

/** /api/v1/proni/export: its JSON error answers (4xx and 5xx). */
export type ProniExportErrorAnswer = unknown;

/** Every v1 route: its variants by name, and its error answer. */
export interface V1Routes {
  elections: {
    variants: {
      record: ElectionsRecordAnswer;
      manifest: ElectionsManifestAnswer;
      summary: ElectionsSummaryAnswer;
      provenance: ElectionsProvenanceAnswer;
      areas: ElectionsAreasAnswer;
      list: ElectionsListAnswer;
      detail: ElectionsDetailAnswer;
      contests: ElectionsContestsAnswer;
      "citations-person": ElectionsCitationsPersonAnswer;
      "citations-contest": ElectionsCitationsContestAnswer;
      "citations-contest-by-name": ElectionsCitationsContestByNameAnswer;
      citations: ElectionsCitationsAnswer;
      "index-of-body": ElectionsIndexOfBodyAnswer;
      index: ElectionsIndexAnswer;
      "contest-by-slug": ElectionsContestBySlugAnswer;
      "contest-by-name": ElectionsContestByNameAnswer;
      contest: ElectionsContestAnswer;
      bundle: ElectionsBundleAnswer;
      election: ElectionsElectionAnswer;
    };
    error: ElectionsErrorAnswer;
  };
  persons: {
    variants: {
      facets: PersonsFacetsAnswer;
      candidacies: PersonsCandidaciesAnswer;
      votes: PersonsVotesAnswer;
      record: PersonsRecordAnswer;
      list: PersonsListAnswer;
    };
    error: PersonsErrorAnswer;
  };
  parties: {
    variants: {
      names: PartiesNamesAnswer;
      folds: PartiesFoldsAnswer;
      profile: PartiesProfileAnswer;
      members: PartiesMembersAnswer;
      record: PartiesRecordAnswer;
      list: PartiesListAnswer;
    };
    error: PartiesErrorAnswer;
  };
  sources: {
    variants: {
      detail: SourcesDetailAnswer;
      record: SourcesRecordAnswer;
      list: SourcesListAnswer;
    };
    error: SourcesErrorAnswer;
  };
  "register-interests": {
    variants: {
      record: RegisterInterestsRecordAnswer;
      list: RegisterInterestsListAnswer;
    };
    error: RegisterInterestsErrorAnswer;
  };
  votes: {
    variants: {
      index: VotesIndexAnswer;
      division: VotesDivisionAnswer;
      shard: VotesShardAnswer;
      person: VotesPersonAnswer;
      party: VotesPartyAnswer;
    };
    error: VotesErrorAnswer;
  };
  graph: {
    variants: {
      manifest: GraphManifestAnswer;
      search: GraphSearchAnswer;
      entity: GraphEntityAnswer;
      slug: GraphSlugAnswer;
      browse: GraphBrowseAnswer;
    };
    error: GraphErrorAnswer;
  };
  stats: {
    variants: {
      counts: StatsCountsAnswer;
    };
    error: StatsErrorAnswer;
  };
  catalogue: {
    variants: {
      pane: CataloguePaneAnswer;
      places: CataloguePlacesAnswer;
      people: CataloguePeopleAnswer;
      agent: CatalogueAgentAnswer;
      "record-by-id": CatalogueRecordByIdAnswer;
      "record-by-slug": CatalogueRecordBySlugAnswer;
      category: CatalogueCategoryAnswer;
      document: CatalogueDocumentAnswer;
    };
    error: CatalogueErrorAnswer;
  };
  layers: {
    variants: {
      index: LayersIndexAnswer;
      document: LayersDocumentAnswer;
      duplicates: LayersDuplicatesAnswer;
      layer: LayersLayerAnswer;
    };
    error: LayersErrorAnswer;
  };
  search: {
    variants: {
      results: SearchResultsAnswer;
    };
    error: SearchErrorAnswer;
  };
  spatial: {
    variants: {
      features: SpatialFeaturesAnswer;
      batch: SpatialBatchAnswer;
    };
    error: SpatialErrorAnswer;
  };
  "data-index": {
    variants: {
      listing: DataIndexListingAnswer;
    };
    error: DataIndexErrorAnswer;
  };
  "proni/node": {
    variants: {
      node: ProniNodeNodeAnswer;
      roots: ProniNodeRootsAnswer;
    };
    error: ProniNodeErrorAnswer;
  };
  "proni/search": {
    variants: {
      results: ProniSearchResultsAnswer;
    };
    error: ProniSearchErrorAnswer;
  };
  "proni/count": {
    variants: {
      count: ProniCountCountAnswer;
    };
    error: ProniCountErrorAnswer;
  };
  "proni/export": {
    variants: {
      csv: ProniExportCsvAnswer;
    };
    error: ProniExportErrorAnswer;
  };
}

export type V1Route = keyof V1Routes;
/** The answer of one route and variant. */
export type V1Answer<R extends V1Route, V extends keyof V1Routes[R]['variants']> = V1Routes[R]['variants'][V];
